from __future__ import annotations

import argparse
import json
import logging

import uvicorn
from dotenv import load_dotenv

from catalyst_router.adapters.alpaca import AlpacaPaperBroker
from catalyst_router.container import Container
from catalyst_router.domain import AgentMode, DecisionRecord
from catalyst_router.service import ReconciliationService
from catalyst_router.settings import Settings


def _check_alpaca(settings: Settings) -> int:
    key, secret = settings.require_alpaca()
    snapshot = AlpacaPaperBroker(key, secret).reconciliation_snapshot()
    print(
        json.dumps(
            {
                "paper": True,
                "market_is_open": snapshot.clock.is_open,
                "equity": str(snapshot.account.equity),
                "buying_power": str(snapshot.account.buying_power),
                "trading_blocked": snapshot.account.trading_blocked,
                "options_trading_level": snapshot.account.options_trading_level,
                "position_count": len(snapshot.positions),
                "open_order_count": len(snapshot.open_orders),
            },
            indent=2,
        )
    )
    return 0


def _reconcile(settings: Settings) -> int:
    container = Container.build(settings)
    snapshot = container.reconciliation_service().reconcile()
    state = container.store.get_agent_state()
    print(
        json.dumps(
            {
                "paper": True,
                "mode": state.mode,
                "reconciled": state.is_reconciled,
                "market_is_open": snapshot.clock.is_open,
                "position_count": len(snapshot.positions),
                "open_order_count": len(snapshot.open_orders),
            },
            indent=2,
        )
    )
    return 0


def _worker(settings: Settings) -> int:
    if settings.runtime_role != "worker":
        raise RuntimeError("worker command requires RUNTIME_ROLE=worker")
    container = Container.build(settings)
    container.trading_worker().run_forever(
        reconcile=container.reconciliation_service().reconcile,
        poll_seconds=settings.worker_poll_seconds,
    )
    return 0


def _set_mode(settings: Settings, mode: AgentMode, reason: str, *, flatten: bool = False) -> int:
    container = Container.build(settings)
    if (flatten or mode is AgentMode.KILLED) and container.broker is None:
        raise RuntimeError("flattening controls require Alpaca credentials")
    if mode is AgentMode.RUNNING:
        if container.broker is None:
            raise RuntimeError("resume requires Alpaca credentials")
        snapshot = container.broker.reconciliation_snapshot()
        ReconciliationService.validate_snapshot(snapshot)
        if snapshot.positions or snapshot.open_orders:
            raise RuntimeError("first-slice resume requires no positions or open orders")
        state = container.store.get_agent_state()
        for client_order_id in state.active_order_ids:
            execution = container.store.get_order(client_order_id)
            if execution is None:
                raise RuntimeError("active order has no durable execution record")
            broker_order = container.broker.get_order_by_client_id(client_order_id)
            status = (
                broker_order.status.rsplit(".", 1)[-1].lower()
                if broker_order is not None
                else "missing"
            )
            terminal = status in {
                "canceled",
                "expired",
                "filled",
                "rejected",
                "replaced",
            }
            expired_and_missing = (
                status == "missing" and snapshot.clock.timestamp >= execution.plan.expires_at
            )
            if not terminal and not expired_and_missing:
                raise RuntimeError("active order is not terminal; refusing resume")
            container.store.clear_active_order(client_order_id)
        if not container.store.get_agent_state().is_reconciled:
            container.reconciliation_service().reconcile()
    record = DecisionRecord.create(
        decision_type="OPERATOR_ACTION",
        summary=f"operator changed mode to {mode}: {reason}",
        payload={"mode": mode, "reason": reason},
    )
    state = container.store.transition_agent_mode(mode, reason=reason, record=record)
    if flatten or mode is AgentMode.KILLED:
        assert container.broker is not None
        container.broker.flatten()
    print(
        json.dumps(
            {
                "paper": True,
                "mode": state.mode,
                "reconciled": state.is_reconciled,
                "reason": state.reason,
            },
            indent=2,
        )
    )
    return 0


def main() -> int:
    load_dotenv()
    logging.basicConfig(level=logging.INFO)
    parser = argparse.ArgumentParser(prog="catalyst-router")
    subparsers = parser.add_subparsers(dest="command", required=True)
    subparsers.add_parser("check-alpaca", help="read and sanitize Alpaca paper account state")
    subparsers.add_parser("reconcile", help="persist a fenced paper-account reconciliation")
    subparsers.add_parser("worker", help="run the always-on inference and trading worker")
    for command in ("resume", "pause", "flatten", "kill"):
        control = subparsers.add_parser(command, help=f"{command} paper execution")
        control.add_argument("--reason", required=True)
    serve = subparsers.add_parser("serve", help="run the local API")
    serve.add_argument("--host", default="127.0.0.1")
    serve.add_argument("--port", type=int, default=8000)
    args = parser.parse_args()

    if args.command == "check-alpaca":
        return _check_alpaca(Settings.from_env())
    if args.command == "reconcile":
        return _reconcile(Settings.from_env())
    if args.command == "worker":
        return _worker(Settings.from_env())
    if args.command == "resume":
        return _set_mode(Settings.from_env(), AgentMode.RUNNING, args.reason)
    if args.command == "pause":
        return _set_mode(Settings.from_env(), AgentMode.PAUSED, args.reason)
    if args.command == "flatten":
        return _set_mode(Settings.from_env(), AgentMode.PAUSED, args.reason, flatten=True)
    if args.command == "kill":
        return _set_mode(Settings.from_env(), AgentMode.KILLED, args.reason)
    if args.command == "serve":
        uvicorn.run("catalyst_router.api:app", host=args.host, port=args.port, reload=False)
        return 0
    parser.error(f"unknown command: {args.command}")
    return 2


if __name__ == "__main__":
    raise SystemExit(main())

from __future__ import annotations

import logging
import time
from collections.abc import Callable
from datetime import UTC, datetime
from pathlib import Path
from typing import Protocol
from uuid import NAMESPACE_URL, uuid5

from catalyst_router.challenger import PublicChallengerStatus, ShadowPrediction
from catalyst_router.domain import DecisionRecord
from catalyst_router.ports import OperationalStore
from catalyst_router.training import FeatureVector, MarketBar, build_feature_vectors

logger = logging.getLogger(__name__)


class MarketData(Protocol):
    def recent_bars(
        self,
        symbols: tuple[str, ...],
        *,
        timeframe_minutes: int,
        lookback_days: int,
    ) -> list[MarketBar]: ...


class ChallengerPredictor(Protocol):
    status: PublicChallengerStatus
    symbols: tuple[str, ...]

    def predict(self, vector: FeatureVector) -> ShadowPrediction: ...


class FeatureBuilder(Protocol):
    def build(self, bars: list[MarketBar]) -> tuple[FeatureVector, ...]: ...


class LiveTrader(Protocol):
    def run(
        self, vectors: tuple[FeatureVector, ...], *, expected_epoch: str
    ) -> tuple[DecisionRecord, ...]: ...


class EventRouter(Protocol):
    def run(
        self, vectors: tuple[FeatureVector, ...], *, expected_epoch: str
    ) -> tuple[DecisionRecord, ...]: ...


class LiveFeatureBuilder:
    def __init__(self, feature_schema: str) -> None:
        self._feature_schema = feature_schema

    def build(self, bars: list[MarketBar]) -> tuple[FeatureVector, ...]:
        return build_feature_vectors(bars, feature_schema=self._feature_schema)


class TradingWorker:
    """Runs the always-on inference cycle; execution remains separately gated."""

    def __init__(
        self,
        *,
        store: OperationalStore,
        market_data: MarketData,
        challenger: ChallengerPredictor,
        feature_builder: FeatureBuilder | None = None,
        live_trader: LiveTrader | None = None,
        event_router: EventRouter | None = None,
        live_started_at: datetime | None = None,
    ) -> None:
        self._store = store
        self._market_data = market_data
        self._challenger = challenger
        self._feature_builder = feature_builder or LiveFeatureBuilder(
            challenger.status.feature_schema or "bar-features-v3"
        )
        self._live_trader = live_trader
        self._event_router = event_router
        self._live_started_at = (
            live_started_at or datetime.now(UTC) if live_trader is not None else None
        )
        self._execution_epoch: str | None = None
        self._bars: dict[tuple[str, datetime], MarketBar] = {}
        self._market_data_bootstrapped = False

    def run_cycle(self) -> tuple[DecisionRecord, ...]:
        state = self._store.get_agent_state()
        if not state.is_reconciled:
            raise RuntimeError("worker execution epoch is not reconciled")
        if self._execution_epoch is not None and state.execution_epoch != self._execution_epoch:
            raise RuntimeError("worker lost execution epoch ownership")
        if not self._challenger.status.deployed or not self._challenger.status.loaded:
            raise RuntimeError("challenger is not ready for inference")
        timeframe = self._challenger.status.timeframe_minutes or 5
        bars = self._market_data.recent_bars(
            self._challenger.symbols,
            timeframe_minutes=timeframe,
            lookback_days=10 if not self._market_data_bootstrapped else 1,
        )
        self._market_data_bootstrapped = True
        self._bars.update({(bar.symbol, bar.timestamp): bar for bar in bars})
        vectors = self._feature_builder.build(list(self._bars.values()))
        if not vectors:
            return ()
        latest_by_symbol: dict[str, datetime] = {}
        for vector in vectors:
            latest_by_symbol[vector.symbol] = max(
                vector.observed_at,
                latest_by_symbol.get(vector.symbol, vector.observed_at),
            )
        latest_vectors = tuple(
            vector for vector in vectors if vector.observed_at == latest_by_symbol[vector.symbol]
        )
        expected_epoch = self._execution_epoch or state.execution_epoch
        records = []
        for vector in latest_vectors:
            prediction = self._challenger.predict(vector)
            record = self._prediction_record(prediction)
            if self._store.append_decision_once(record, expected_epoch=expected_epoch):
                records.append(record)
        if self._event_router is not None:
            try:
                records.extend(
                    self._event_router.run(latest_vectors, expected_epoch=expected_epoch)
                )
            except Exception:
                logger.exception("shadow event routing failed; live trading remains enabled")
        if self._live_trader is not None:
            eligible_vectors = tuple(
                vector
                for vector in latest_vectors
                if self._live_started_at is None or vector.observed_at > self._live_started_at
            )
            live_vectors = tuple(
                vector
                for vector in eligible_vectors
                if self._store.append_decision_once(
                    self._live_claim_record(vector), expected_epoch=expected_epoch
                )
            )
            if not live_vectors:
                return tuple(records)
            records.extend(self._live_trader.run(live_vectors, expected_epoch=expected_epoch))
        return tuple(records)

    def run_forever(
        self,
        *,
        reconcile: Callable[[], object],
        poll_seconds: int = 15,
        sleep: Callable[[float], None] = time.sleep,
        heartbeat_path: Path = Path("/tmp/worker-heartbeat"),
    ) -> None:
        reconcile()
        state = self._store.get_agent_state()
        if not state.is_reconciled:
            raise RuntimeError("startup reconciliation did not complete")
        self._execution_epoch = state.execution_epoch
        consecutive_failures = 0
        while True:
            try:
                records = self.run_cycle()
                consecutive_failures = 0
                if records:
                    logger.info("persisted %d worker decisions", len(records))
                heartbeat_path.touch()
            except Exception:
                consecutive_failures += 1
                logger.exception("trading worker cycle failed")
                if consecutive_failures >= 5:
                    raise
            sleep(poll_seconds)

    def _prediction_record(self, prediction: ShadowPrediction) -> DecisionRecord:
        authority = self._challenger.status.authority or "SHADOW_ONLY"
        model_label = "paper-live model" if authority == "PAPER_LIVE" else "shadow model"
        decision_id = str(
            uuid5(
                NAMESPACE_URL,
                ":".join(
                    (
                        "challenger-prediction",
                        prediction.run_id,
                        prediction.symbol,
                        prediction.observed_at.isoformat(),
                    )
                ),
            )
        )
        return DecisionRecord.create(
            decision_id=decision_id,
            decision_type="CHALLENGER_PREDICTION",
            occurred_at=prediction.observed_at,
            symbol=prediction.symbol,
            summary=(
                f"{model_label} {prediction.run_id} predicted {prediction.value:.6f} "
                f"({prediction.signal})"
            ),
            payload={
                "authority": authority,
                "run_id": prediction.run_id,
                "value": prediction.value,
                "signal": prediction.signal,
            },
            public=True,
            public_summary=f"{model_label.title()} signal: {prediction.signal}",
        )

    def _live_claim_record(self, vector: FeatureVector) -> DecisionRecord:
        run_id = self._challenger.status.run_id or "unknown-model"
        return DecisionRecord.create(
            decision_id=str(
                uuid5(
                    NAMESPACE_URL,
                    ":".join(
                        (
                            "live-bar-evaluation",
                            run_id,
                            vector.symbol,
                            vector.observed_at.isoformat(),
                        )
                    ),
                )
            ),
            decision_type="LIVE_BAR_EVALUATION_CLAIM",
            occurred_at=vector.observed_at,
            symbol=vector.symbol,
            summary=f"claimed one live evaluation for {run_id}",
        )

from decimal import ROUND_FLOOR, Decimal

from catalyst_router.domain import (
    AgentMode,
    AgentState,
    InstrumentType,
    PortfolioRiskState,
    RiskDecision,
    RiskDecisionStatus,
    Route,
    Side,
    TradeIntent,
)


class RiskGovernor:
    MAX_POSITIONS = 6
    MAX_TRADE_RISK_RATE = Decimal("0.01")
    REDUCED_TRADE_RISK_RATE = Decimal("0.005")
    MAX_TOTAL_RISK_RATE = Decimal("0.04")
    MAX_OVERNIGHT_RISK_RATE = Decimal("0.02")
    MAX_GROUP_RISK_RATE = Decimal("0.02")
    DE_RISK_DAILY_LOSS_RATE = Decimal("0.02")
    MAX_DAILY_LOSS_RATE = Decimal("0.04")
    MAX_COMPETITION_DRAWDOWN_RATE = Decimal("0.12")
    MAX_QUOTE_AGE_SECONDS = Decimal("5")

    def __init__(self, *, options_execution_enabled: bool = False) -> None:
        self._options_execution_enabled = options_execution_enabled

    def evaluate(
        self,
        intent: TradeIntent,
        agent: AgentState,
        portfolio: PortfolioRiskState,
        *,
        market_is_open: bool,
        overnight: bool = False,
        trading_blocked: bool = False,
    ) -> RiskDecision:
        vetoes: list[str] = []
        if intent.route is Route.NO_TRADE:
            vetoes.append("NO_TRADE cannot create exposure")
        if intent.instrument_type is InstrumentType.OPTION and intent.side is not Side.BUY:
            vetoes.append("short option legs are prohibited")
        if intent.instrument_type is InstrumentType.OPTION and not self._options_execution_enabled:
            vetoes.append("live option execution is not enabled")
        if intent.route is Route.LIQUIDITY_REVERSION and (
            intent.instrument_type is not InstrumentType.EQUITY
        ):
            vetoes.append("liquidity reversion must use equities")
        if intent.route is Route.REGIME_TREND and (
            intent.instrument_type is not InstrumentType.EQUITY
        ):
            vetoes.append("regime trend must use equities")
        if trading_blocked:
            vetoes.append("Alpaca account is blocked from trading")
        if agent.mode is not AgentMode.RUNNING:
            vetoes.append(f"agent mode is {agent.mode}")
        if not agent.is_reconciled:
            vetoes.append("startup reconciliation is incomplete")
        if not market_is_open:
            vetoes.append("market is closed")
        if not intent.data_quality_passed:
            vetoes.append("intent data failed quality gates")
        if intent.quote_age_seconds > self.MAX_QUOTE_AGE_SECONDS:
            vetoes.append("quote is stale")
        if intent.stop_distance <= 0:
            vetoes.append("stop distance must be positive")
        if intent.side is Side.BUY and intent.stop_price >= intent.entry_price:
            vetoes.append("buy stop must be below entry")
        if intent.side is Side.SELL and intent.stop_price <= intent.entry_price:
            vetoes.append("sell stop must be above entry")
        if portfolio.position_count >= self.MAX_POSITIONS:
            vetoes.append("maximum position count reached")

        daily_loss = max(Decimal("0"), -portfolio.daily_pnl)
        if daily_loss >= portfolio.equity * self.MAX_DAILY_LOSS_RATE:
            vetoes.append("daily loss circuit breaker reached")
        if portfolio.competition_drawdown >= self.MAX_COMPETITION_DRAWDOWN_RATE:
            vetoes.append("competition drawdown kill threshold reached")

        if vetoes:
            return self._veto(intent, vetoes)

        risk_rate = (
            self.REDUCED_TRADE_RISK_RATE
            if daily_loss >= portfolio.equity * self.DE_RISK_DAILY_LOSS_RATE
            else self.MAX_TRADE_RISK_RATE
        )
        allowed_risk = portfolio.equity * risk_rate
        total_capacity = portfolio.equity * self.MAX_TOTAL_RISK_RATE - portfolio.total_open_risk
        group_capacity = (
            portfolio.equity * self.MAX_GROUP_RISK_RATE
            - portfolio.group_open_risk.get(intent.exposure_group, Decimal("0"))
        )
        capacities = [allowed_risk, total_capacity, group_capacity]
        if overnight:
            capacities.append(
                portfolio.equity * self.MAX_OVERNIGHT_RISK_RATE - portfolio.overnight_open_risk
            )
        risk_amount = max(Decimal("0"), min(capacities))
        affordable = (portfolio.buying_power / intent.entry_cost_per_unit).to_integral_value(
            rounding=ROUND_FLOOR
        )
        by_stop = (risk_amount / intent.stop_risk_per_unit).to_integral_value(rounding=ROUND_FLOOR)
        quantity = int(min(affordable, by_stop))
        if quantity < 1:
            return self._veto(intent, ["risk or buying-power capacity is insufficient"])

        actual_risk = intent.stop_risk_per_unit * quantity
        status = (
            RiskDecisionStatus.REDUCED
            if risk_amount < allowed_risk or risk_rate < self.MAX_TRADE_RISK_RATE
            else RiskDecisionStatus.APPROVED
        )
        return RiskDecision(
            status=status,
            intent_id=intent.intent_id,
            quantity=quantity,
            risk_amount=actual_risk,
            checks=(
                "agent running and reconciled",
                "data and market gates passed",
                "trade, portfolio, group, and buying-power limits passed",
            ),
        )

    @staticmethod
    def _veto(intent: TradeIntent, vetoes: list[str]) -> RiskDecision:
        return RiskDecision(
            status=RiskDecisionStatus.VETOED,
            intent_id=intent.intent_id,
            quantity=0,
            risk_amount=Decimal("0"),
            checks=tuple(vetoes),
        )

from __future__ import annotations

from decimal import Decimal
from typing import cast

from alpaca.common.exceptions import APIError
from alpaca.trading.client import TradingClient
from alpaca.trading.enums import OrderClass, OrderSide, QueryOrderStatus, TimeInForce
from alpaca.trading.models import Clock, Order, Position, TradeAccount
from alpaca.trading.requests import (
    GetOrdersRequest,
    LimitOrderRequest,
    StopLossRequest,
    TakeProfitRequest,
)

from catalyst_router.domain import (
    AccountSnapshot,
    BrokerOrderSnapshot,
    MarketClockSnapshot,
    OpenOrderSnapshot,
    OrderPlan,
    PositionSnapshot,
    ReconciliationSnapshot,
    Side,
)

ALPACA_PAPER_BASE_URL = "https://paper-api.alpaca.markets"
ALPACA_PAPER_API_ROOT = f"{ALPACA_PAPER_BASE_URL}/v2"
# Alpaca reports a filled bracket's exits as an OCO pair: the working leg is
# "new" while its resting sibling is "held". A held leg is live server-side
# protection, so excluding it would read every protected position as unprotected.
_ACTIVE_PROTECTIVE_STATUSES = {
    "accepted",
    "held",
    "new",
    "partially_filled",
    "pending_new",
}


class AlpacaPaperBroker:
    """Alpaca adapter hard-pinned to the paper-trading endpoint."""

    def __init__(self, key: str, secret: str) -> None:
        self._client = TradingClient(
            key,
            secret,
            paper=True,
            url_override=ALPACA_PAPER_BASE_URL,
        )

    def reconciliation_snapshot(self) -> ReconciliationSnapshot:
        account = cast(TradeAccount, self._client.get_account())
        clock = cast(Clock, self._client.get_clock())
        positions = cast(list[Position], self._client.get_all_positions())
        orders = cast(
            list[Order],
            self._client.get_orders(
                filter=GetOrdersRequest(status=QueryOrderStatus.OPEN, limit=500)
            ),
        )
        return ReconciliationSnapshot(
            account=AccountSnapshot(
                equity=Decimal(str(account.equity)),
                buying_power=Decimal(str(account.buying_power)),
                cash=Decimal(str(account.cash)),
                portfolio_value=Decimal(str(account.portfolio_value)),
                trading_blocked=bool(account.trading_blocked),
                options_trading_level=int(account.options_trading_level or 0),
                last_equity=(
                    Decimal(str(account.last_equity)) if account.last_equity is not None else None
                ),
            ),
            clock=MarketClockSnapshot(
                is_open=bool(clock.is_open),
                timestamp=clock.timestamp,
                next_open=clock.next_open,
                next_close=clock.next_close,
            ),
            positions=tuple(
                PositionSnapshot(
                    symbol=position.symbol,
                    asset_class=str(position.asset_class),
                    quantity=Decimal(str(position.qty)),
                    market_value=Decimal(str(position.market_value or 0)),
                    unrealized_pl=Decimal(str(position.unrealized_pl or 0)),
                )
                for position in positions
            ),
            open_orders=tuple(
                OpenOrderSnapshot(
                    client_order_id=order.client_order_id,
                    symbol=order.symbol or "",
                    status=str(order.status),
                    side=str(order.side or ""),
                    quantity=Decimal(str(order.qty)) if order.qty is not None else None,
                )
                for order in orders
            ),
        )

    def get_order_by_client_id(self, client_order_id: str) -> BrokerOrderSnapshot | None:
        try:
            order = cast(Order, self._client.get_order_by_client_id(client_order_id))
        except APIError as exc:
            if exc.status_code == 404:
                return None
            raise
        return self._order_snapshot(order)

    def submit_order(self, plan: OrderPlan) -> BrokerOrderSnapshot:
        order = cast(
            Order,
            self._client.submit_order(
                LimitOrderRequest(
                    symbol=plan.symbol,
                    qty=plan.quantity,
                    side=OrderSide.BUY if plan.side is Side.BUY else OrderSide.SELL,
                    time_in_force=TimeInForce.DAY,
                    order_class=OrderClass.BRACKET,
                    extended_hours=False,
                    client_order_id=plan.client_order_id,
                    limit_price=float(plan.limit_price),
                    take_profit=TakeProfitRequest(limit_price=float(plan.take_profit_price)),
                    stop_loss=StopLossRequest(stop_price=float(plan.stop_price)),
                )
            ),
        )
        return self._order_snapshot(order)

    def close_position(self, symbol: str) -> None:
        """Cancels the symbol's resting bracket legs, then closes just that position."""
        orders = cast(
            list[Order],
            self._client.get_orders(
                filter=GetOrdersRequest(status=QueryOrderStatus.OPEN, symbols=[symbol], limit=500)
            ),
        )
        for order in orders:
            try:
                self._client.cancel_order_by_id(str(order.id))
            except APIError as exc:
                if exc.status_code not in {404, 422}:
                    raise
        try:
            self._client.close_position(symbol)
        except APIError as exc:
            if exc.status_code != 404:
                raise

    def flatten(self) -> None:
        self._client.close_all_positions(cancel_orders=True)

    @staticmethod
    def _order_snapshot(order: Order) -> BrokerOrderSnapshot:
        if order.symbol is None or order.side is None or order.qty is None:
            raise RuntimeError("Alpaca order response is incomplete")
        active_legs = [
            leg
            for leg in getattr(order, "legs", None) or []
            if str(leg.status).rsplit(".", 1)[-1].lower() in _ACTIVE_PROTECTIVE_STATUSES
        ]
        return BrokerOrderSnapshot(
            order_id=str(order.id),
            client_order_id=order.client_order_id,
            symbol=order.symbol,
            side=Side.BUY if order.side == OrderSide.BUY else Side.SELL,
            quantity=int(Decimal(str(order.qty))),
            status=str(order.status),
            has_active_take_profit=any(
                str(leg.type).rsplit(".", 1)[-1].lower() == "limit" for leg in active_legs
            ),
            has_active_stop_loss=any(
                str(leg.type).rsplit(".", 1)[-1].lower() in {"stop", "stop_limit"}
                for leg in active_legs
            ),
        )

